function setId(s){s=String(s||'').toUpperCase();if(['PA','PROMO-A','P-A'].includes(s))return 'P-A';if(['PB','PROMO-B','P-B'].includes(s))return 'P-B';return s.replace(/^([ABC]\d+)([A-Z])$/,(m,a,b)=>a+b.toLowerCase());}
