 if(s==='Ancient Pokémon')return {tag:'Ancient'};
 if(s==='Future Pokémon')return {tag:'Future'};
 if(s==='Ultra Beast'||s==='Ultra Beasts')return {tag:'Ultra Beast'};
 if(s==='Pokémon')return {};
 if(/Pokémon|Ultra Beast|Ancient|Future/.test(s))return null;
